/* Therapeutics Exam 3: IBS, constipation, diarrhea, IBD, peptic ulcer disease, hemorrhoids and GI tests (from the lecture slides and class questions) */
/* Three categories: TH3F = IBS, constipation and diarrhea; TH3C = contraceptives (th3c.js); TH3 = everything else */
const T = (t, d, q, a, w, e, s) => Q(/^(Diarrhea|Constipation|IBS|Opioid-induced)/.test(t) ? "TH3F" : "TH3", d, q, a, w, e, t, s);

/* ---------- Diarrhea ---------- */
T("Diarrhea",2,"A 26-year-old has had six loose stools and cramping for 18 hours, with no fever or blood. Yesterday they ate at a street fair. Ibuprofen and cannabis use were occasional. What is the most likely cause?","A food- or waterborne organism picked up at the street fair",["Early type 2 diabetes","HIV infection","An ibuprofen and cannabis interaction"],"Sudden onset, no red flags and a recent food exposure point to infectious acute diarrhea. Family history of diabetes does not explain it.");
T("Diarrhea",1,"Diarrhea caused by a stimulating substance that increases secretion or decreases absorption of water and electrolytes is called:","Secretory diarrhea",["Osmotic diarrhea","Exudative diarrhea","Transitory diarrhea"],"Secretory diarrhea comes from toxins, hormones or stimulant laxatives that drive fluid into the lumen. Osmotic diarrhea is from poorly absorbed solutes.");
T("Diarrhea",1,"Which statement about acute diarrhea is true?","It is self-limiting and usually subsides within 72 hours",["It is mainly secondary to chronic diseases such as diabetes","It is treated with bulk-forming laxatives","It is a chronic condition that waxes and wanes for many years"],"Acute diarrhea lasts under 14 days and most cases resolve in about 72 hours with fluids and supportive care.");
T("Diarrhea",1,"How long do symptoms last in acute, persistent and chronic diarrhea?","Acute under 14 days, persistent over 14 days, chronic over 30 days",["Acute under 3 days, persistent over 7 days, chronic over 14 days","Acute under 30 days, persistent over 60 days, chronic over 90 days","Acute under 7 days, persistent over 30 days, chronic over 60 days"],"Duration separates the types: acute under 14 days, persistent over 14 days and chronic over 30 days.");
T("Diarrhea",2,"A patient asks how to prevent diarrhea on a trip to a developing country next month. What is the most appropriate advice?","Use bismuth subsalicylate as needed",["Eat fresh vegetables and drink tap water","Avoid all meat products","Take loperamide around the clock for 48 hours before travel"],"Bismuth subsalicylate can reduce traveler's diarrhea. Raw produce and tap water are the usual sources, and loperamide is for treatment, not routine prevention.");
T("Diarrhea",3,"A 53-year-old has three loose stools, a fever of 101.7 F, normal vitals and hives with penicillin and aspirin. What is the best recommendation?","Increase fluid intake and rest the gut (withhold food) until symptoms resolve",["Bismuth subsalicylate 525 mg every hour as needed","Loperamide 4 mg then 2 mg after each loose stool","Stop home medications and start 5 days of antibiotics"],"Bismuth subsalicylate is contraindicated with aspirin allergy. Loperamide should be avoided with fever because that suggests infectious diarrhea. Fluids and a short gut rest are the safe choice.");
T("Diarrhea",3,"A lethargic, irritable 3-year-old with fever has had diarrhea for 2 days, vomits after sips of water and refuses food. What is the most appropriate rehydration approach?","Obtain laboratory values and start IV fluids",["Switch to a commercial oral rehydration solution","Give a homemade WHO-recipe solution every hour","Continue bottled water only"],"Lethargy and failure of oral intake signal moderate to severe dehydration. This child needs evaluation and IV fluids rather than oral rehydration at home.");
T("Diarrhea",2,"Which fluid is first line for rehydration in acute diarrhea?","Oral rehydration solution (ORS)",["Sports drinks with added sugar and caffeine","Apple juice","Plain water"],"ORS contains glucose and sodium for coupled absorption. Juice and sports drinks have too much sugar and too little sodium.");
T("Diarrhea",2,"Which supplement is added to oral rehydration in children 5 years old or younger?","Zinc",["Iron","Vitamin C","Calcium"],"Zinc shortens the course of diarrhea and reduces recurrence in young children.");
T("Diarrhea",2,"What are the OTC dosing and age limits for loperamide?","4 mg first dose, then 2 mg after each loose stool, for ages 2 and older, with a referral if it lasts beyond 48 hours",["2 mg every hour for ages 6 and older","8 mg first dose, then 4 mg daily, for adults only","4 mg every 4 hours for ages 12 and older"],"Loperamide is OTC at 4 mg then 2 mg per loose stool, to a maximum of 8 mg per day OTC. Refer if symptoms last over 48 hours.");
T("Diarrhea",3,"When should loperamide be avoided?","Bloody diarrhea or fever suggesting infection",["Mild diarrhea after a large meal","Traveler's diarrhea without fever","Diarrhea in a patient who is also taking a proton pump inhibitor"],"Slowing motility in invasive infections can worsen illness. Loperamide at high doses also carries a boxed warning for torsades and cardiac events.");
T("Diarrhea",2,"Diphenoxylate/atropine (Lomotil) is classified as which schedule and used from what age?","Schedule V, age 6 and older",["Schedule II, age 18 and older","Schedule IV, age 2 and older","Not scheduled, any age"],"Lomotil is C-V because diphenoxylate is an opioid. The atropine discourages misuse.");
T("Diarrhea",2,"Which patient should NOT use bismuth subsalicylate?","A patient with aspirin allergy or on other salicylates",["A healthy adult with traveler's diarrhea and no other medical problems","An adult with mild loose stools after eating spicy food","A patient taking a multivitamin"],"Bismuth subsalicylate is a salicylate. Avoid it with aspirin allergy, other salicylates, ulcers, bloody stools, and in children with chickenpox or influenza because of Reye syndrome.");
T("Diarrhea",1,"Bismuth subsalicylate can cause which harmless effect that patients should be warned about?","Black tongue and black stools",["Red urine that lasts for several days after each dose","Green skin","Yellow eyes"],"Bismuth reacts with sulfur to form bismuth sulfide, which darkens the tongue and stool. It can be mistaken for bleeding.");
T("Diarrhea",3,"Which drug treats secretory diarrhea from carcinoid tumors?","Octreotide",["Loperamide","Lactase","Kaolin-pectin"],"Octreotide is a somatostatin analog that reduces the hormone-driven secretion.");
T("Diarrhea",1,"Which are common probiotic organisms used for diarrhea?","Lactobacillus and Saccharomyces",["Clostridium and Bacteroides","Escherichia and Salmonella","Staphylococcus and Streptococcus"],"Lactobacillus and Saccharomyces boulardii are commonly marketed, with modest benefit.");
T("Diarrhea",1,"Lactase supplements help with which cause of diarrhea?","Lactose intolerance",["Celiac disease","Carcinoid syndrome","C. difficile infection"],"Lactase replaces the missing enzyme so lactose is not left to cause osmotic diarrhea.");

/* ---------- Constipation ---------- */
T("Constipation",1,"Which statement about constipation is true?","Decreased fiber intake can lead to constipation",["Patients describe it in easily quantified measures","A daily bowel movement is required for health","Healthy people pass at least six stools a week"],"Fiber adds bulk and softens stool. Normal frequency ranges widely, and constipation is generally fewer than three stools per week.");
T("Constipation",1,"Which is a possible medical cause of constipation?","Hypothyroidism",["Osteoporosis treated with weight-bearing exercise","Hypertension","Eczema"],"Hypothyroidism slows gut transit. Diabetes, Parkinson disease and depression are other examples.");
T("Constipation",2,"Which drug classes are commonly constipating?","Anticholinergics, opioids and aluminum or calcium antacids",["Loop diuretics, ACE inhibitors and thiazide diuretics","Penicillins, macrolides and fluoroquinolones","Statins, fibrates and ezetimibe"],"Anticholinergic effects and opioid mu agonism slow motility. Calcium, aluminum, iron and calcium channel blockers also contribute.");
T("Constipation",2,"Which finding is an alarm symptom that calls for referral rather than self-treatment?","Blood in the stool, unintentional weight loss or anemia",["Hard stools for two days after a change in diet","Occasional straining after a low-fiber meal","Mild bloating that comes and goes after meals"],"Alarm features suggest organic disease such as colorectal cancer and need medical evaluation.");
T("Constipation",3,"A 30-year-old eats 12-15 g of fiber a day, drinks plenty of water, exercises and has hard stools every 2-3 days. What is the best first recommendation?","Increase dietary fiber to 20 to 30 g per day",["Restrict fluids to 1.5 L per day and avoid exercise","Start biofeedback therapy","Start bisacodyl 10 mg"],"Their fluid and activity are already good, but fiber is low. Adjust diet first and add fiber gradually.");
T("Constipation",3,"A patient with constipation returns after a few weeks with no relief from more dietary fiber plus methylcellulose. What is the next step?","Polyethylene glycol 3350, 17 g by mouth once daily",["Magnesium citrate 300 mL once every day for a week","Linaclotide 145 mcg daily","Referral for colonoscopy"],"PEG 3350 is the strongly recommended osmotic laxative for chronic constipation. Alarm symptoms are absent, so no colonoscopy is needed yet.");
T("Constipation",1,"How should bulk-forming laxatives such as psyllium, methylcellulose and polycarbophil be taken?","With a full glass of water, separated from other medications by 2 hours",["On an empty stomach with no fluid","Only at bedtime without water","Together with all other medications"],"They need fluid to prevent obstruction and can bind other drugs, so separate doses.");
T("Constipation",1,"What is the maximum daily dose of OTC polyethylene glycol 3350?","34 g (17 g once daily is standard)",["8.5 g (half of the standard dose)","68 g","100 g"],"MiraLAX is 17 g in 8 oz of fluid daily, and up to 34 g per day is the most used.");
T("Constipation",2,"Which laxative is a stool softener rather than a stimulant or osmotic?","Docusate",["Bisacodyl","Senna","Magnesium citrate"],"Docusate is an emollient with weak evidence. Prefer fiber or PEG for real constipation.");
T("Constipation",2,"What caution applies to sodium phosphate (Fleet) enemas and magnesium laxatives?","Avoid in kidney disease, and use sodium phosphate cautiously, especially in older adults",["They are safest for long-term daily use in older adults","They require a pregnancy test before every single dose","They should only ever be taken together with a fiber supplement"],"Phosphate and magnesium can accumulate with renal impairment. Phosphate enemas are best avoided in older adults.");
T("Constipation",2,"Which agents are stimulant laxatives?","Bisacodyl, senna and castor oil",["Psyllium, polycarbophil and methylcellulose","Lactulose, PEG and glycerin","Docusate and mineral oil"],"Stimulants act on the myenteric plexus. Guidelines support short-term use, for under 4 weeks.");
T("Constipation",2,"Lubiprostone works by:","Activating type 2 chloride channels in the gut lumen",["Activating guanylate cyclase C receptors on the gut surface","Agonizing 5-HT4 receptors","Blocking mu opioid receptors"],"Chloride secretion draws water into the lumen. Take it with food, and it is for women in IBS-C. Check a pregnancy test first.");
T("Constipation",3,"Linaclotide and plecanatide are:","Guanylate cyclase-C agonists taken on an empty stomach",["Chloride channel activators taken with food twice daily","5-HT4 agonists taken at bedtime with food","Mu opioid antagonists taken with the first meal"],"Take them about 30 minutes before the first meal. Diarrhea is the main side effect, and they are contraindicated in young children.");
T("Constipation",3,"Which 5-HT4 agonists are used for constipation, with a warning about suicidal thoughts?","Prucalopride and tegaserod",["Linaclotide and plecanatide","Naloxegol and naldemedine","Lubiprostone and tenapanor"],"Tegaserod was withdrawn in 2007 for cardiovascular risk and re-approved in 2019 with restrictions.");
T("Constipation",3,"Which laxative recommendation for chronic idiopathic constipation is STRONG in the 2023 AGA guideline?","Polyethylene glycol",["Senna","Lactulose","Magnesium oxide"],"PEG, linaclotide, plecanatide and prucalopride are strong. Fiber, magnesium oxide, senna and lactulose are conditional.");
T("Constipation",2,"What is the first-line treatment for constipation in children?","Polyethylene glycol",["Lubiprostone twice daily with food","Prucalopride","Domperidone"],"PEG is first line for pediatric constipation. Avoid lubiprostone, prucalopride and domperidone in children.");
T("Constipation",2,"Which treatments are safe in pregnancy?","Fiber, bulk-forming laxatives, PEG and lactulose",["Castor oil, mineral oil and stimulant enemas every day","Magnesium citrate in large doses every day for weeks","Lubiprostone without testing"],"Castor oil can stimulate the uterus and mineral oil impairs vitamin absorption.");
T("Constipation",3,"Which is the preferred option for an older adult with constipation?","Polyethylene glycol, or a glycerin suppository",["A sodium phosphate enema used every day","Mineral oil at bedtime taken while lying down","Magnesium citrate every day for several weeks"],"PEG is preferred over lactulose, and glycerin suppositories are safer than phosphate enemas.");
T("Constipation",3,"A patient taking clozapine has constipation. Why is this important?","Clozapine causes severe GI hypomotility, which can lead to ileus",["Clozapine causes diarrhea only and never constipation","It is a harmless nuisance that never needs follow up","It only occurs in children and teenagers on clozapine"],"Serious hypomotility can lead to obstruction. Treat early and monitor.");

/* ---------- Opioid-induced constipation ---------- */
T("Opioid-induced constipation",2,"What is the first-line approach for opioid-induced constipation?","A laxative such as PEG, bisacodyl or lactulose",["A PAMORA","Loperamide","Bismuth subsalicylate every four hours"],"Start with laxatives, then add a peripherally acting mu-opioid receptor antagonist (PAMORA) if the response is inadequate.");
T("Opioid-induced constipation",2,"Which drugs are PAMORAs?","Methylnaltrexone, naloxegol and naldemedine",["Naloxone, naltrexone, nalbuphine and buprenorphine","Linaclotide, plecanatide, lubiprostone and tenapanor","Prucalopride, tegaserod, bisacodyl and senna"],"PAMORAs block gut mu receptors without reversing analgesia. Naloxone and naltrexone cross into the brain and could cause withdrawal.");
T("Opioid-induced constipation",3,"Which administration instruction is correct for naloxegol?","Take on an empty stomach",["Take with a high-fat meal","Inject subcutaneously","Take only at bedtime with food"],"Food increases absorption and the risk of abdominal pain. Naldemedine can be taken with or without food, and methylnaltrexone is injected subcutaneously with site rotation.");
T("Opioid-induced constipation",3,"Which agent is approved for use only in the hospital for short-term use?","Alvimopan",["Lubiprostone","Methylnaltrexone","Naloxegol"],"Alvimopan is a peripheral mu antagonist limited to inpatient use for about 15 doses, labeled for postoperative ileus. The outpatient drugs are naloxegol, naldemedine and methylnaltrexone.");

/* ---------- IBS ---------- */
T("IBS",1,"Which foods are high in FODMAPs and may worsen IBS symptoms?","Dairy milk, yogurt and ice cream",["Eggs and meat","Rice, quinoa and oats","Grapes, oranges and strawberries"],"Lactose is a fermentable sugar. Eggs, meat, rice, oats and several fruits are low FODMAP.");
T("IBS",2,"Which fiber is suggested for IBS, at what daily amount?","Soluble fiber such as psyllium, 20 to 30 g per day",["Insoluble wheat bran, 5 g per day, taken with meals","No fiber at all, to avoid bloating and gas","Methylcellulose only, 50 g per day"],"Increase slowly. Soluble fiber is better tolerated than bran.");
T("IBS",2,"Which treatment is recommended for mild constipation-predominant IBS?","Polyethylene glycol",["Saline cathartics such as magnesium citrate each day","Loperamide","Mineral oil"],"PEG is a first-line osmotic option for IBS-C. Linaclotide has the best evidence of the secretagogues.");
T("IBS",2,"For IBS-associated abdominal pain, which drug class is recommended?","Tricyclic antidepressants such as amitriptyline",["Antispasmodics","Bupropion started at the highest dose","SSRIs such as sertraline or escitalopram"],"TCAs are recommended for pain. The slides list antispasmodics and non-TCA antidepressants as not recommended.");
T("IBS",3,"A 43-year-old with IBS-D has abdominal pain, bloating and loose stools. They had a cholecystectomy 4 years ago and cannot stay on a low-FODMAP diet. Which treatment is most appropriate?","Rifaximin 550 mg three times daily for 2 weeks",["Eluxadoline","Linaclotide 290 mcg once daily on an empty stomach","Alosetron"],"Eluxadoline must be avoided without a gallbladder. Linaclotide is for IBS-C. Alosetron is for women with severe IBS-D that failed other therapy, so rifaximin is the best choice here.");
T("IBS",3,"Which patient should avoid eluxadoline?","One without a gallbladder, with pancreatitis, or drinking more than 3 alcoholic drinks per day",["One who has never had a gallbladder problem or taken any daily medicines at all","One with IBS-C and no other conditions","One older than 40 with no history of abdominal surgery"],"Risk of pancreatitis, sphincter of Oddi spasm and constipation. It activates opioid receptors, so the Schedule IV status is relevant.");
T("IBS",3,"What is the boxed warning for alosetron?","Serious complications of constipation, including ischemic colitis",["Severe hepatotoxicity and liver failure requiring transplant evaluation","QT prolongation and torsades de pointes","Suicidality in teenagers and young adults"],"Alosetron blocks 5-HT3 receptors. It is approved for women with severe IBS-D who failed other therapy. Stop it if constipation develops.");
T("IBS",2,"Tenapanor treats IBS-C by:","Inhibiting the sodium/hydrogen exchanger NHE3",["Activating guanylate cyclase C in the intestinal lumen","Blocking 5-HT3 receptors on enteric neurons","Activating chloride channels"],"The usual dose is 50 mg twice daily, taken just before meals.");
T("IBS",2,"Which statement about rifaximin for IBS-D is true?","It is a non-absorbed antibiotic, 550 mg three times daily for 2 weeks, which can be repeated",["It is absorbed systemically and must be given for life at a high dose","It is only used for IBS-C and never for IBS-D or any other diarrhea condition","It is a 5-HT3 blocker that is taken twice daily with food"],"It improves bloating, pain and watery stools but is costly.");
T("IBS",1,"Which OTC option may help IBS symptoms and has some evidence?","Peppermint oil",["Aspirin","Bisacodyl 10 mg every day for a month","Docusate"],"Peppermint oil is an antispasmodic that can reduce cramping. Probiotics such as Bifidobacterium have limited evidence too.");

/* ---------- Evaluation of the GI tract (Hemmer, Oct 30 2026) ---------- */
T("GI evaluation",1,"Bleeding from the upper GI tract is most likely to present as:","Hematemesis or melena",["Bright red blood in the stool (hematochezia) only","Mucus in the stool only","Pencil-thin stools"],"The upper GI tract (esophagus, stomach, duodenum) causes about 80% of GI bleeding. Blood is partly digested, giving coffee-ground vomit or dark, tarry stool. Bright red blood in stool points lower.","GI Evaluation lecture, slide 4");
T("GI evaluation",1,"A patient reports bright red blood mixed in the stool. This finding is called:","Hematochezia, which is more typical of lower GI bleeding",["Melena, which is typical of lower GI bleeding","Hematemesis, which is typical of upper GI bleeding","Melena, which is typical of upper GI bleeding"],"Hematochezia is bright red blood per rectum and usually comes from the lower tract. Melena is digested blood that is dark and sticky, usually from the upper tract.","GI Evaluation lecture, slide 4");
T("GI evaluation",2,"Which imaging test is the LEAST sensitive but can quickly show bowel obstruction or perforation?","Plain abdominal film (X-ray)",["MRI of the abdomen with and without contrast","CT with contrast","Capsule endoscopy"],"Plain films show the size and location of bowel and can diagnose obstruction, perforation and toxic megacolon, but they miss most mucosal disease.","GI Evaluation lecture, slide 6");
T("GI evaluation",2,"Which test introduces contrast directly into the small bowel through a nasoduodenal tube?","Enteroclysis",["Lower GI series","Swallow study","Upper GI series"],"Enteroclysis delivers barium straight into the small intestine for better detail. A lower GI series uses an enema, and an upper GI series uses swallowed contrast.","GI Evaluation lecture, slide 9");
T("GI evaluation",2,"Why might MRI be chosen over CT for a young patient with Crohn's disease?","It has no radiation exposure and they will need repeated bowel imaging over a lifetime",["It is cheaper than CT and also available in every emergency room","It is safe in patients with pacemakers","It is better at finding gas in the bowel"],"A CT chest carries about 70 times the radiation of a chest X-ray. MRI avoids radiation but costs more and is contraindicated with pacemakers and some metallic implants.","GI Evaluation lecture, slide 14");
T("GI evaluation",1,"What is a limitation of trans-abdominal ultrasound for GI imaging?","Image quality is reduced by bowel gas, body fat and operator skill",["It exposes the patient to high radiation","It cannot be used to look at the gallbladder, liver or any other organ","It requires barium ingestion"],"Ultrasound is non-invasive and inexpensive and is used for the gallbladder, liver and kidneys, but images are less clear than CT or MRI.","GI Evaluation lecture, slide 15");
T("GI evaluation",2,"Which endoscopic option is used to view the jejunum and ileum, which standard scopes do not reach well?","Capsule endoscopy",["Esophagogastroduodenoscopy","Flexible sigmoidoscopy","Colonoscopy alone"],"EGD reaches the proximal small bowel and colonoscopy the colon, but the jejunum and ileum are poorly seen. The patient swallows a wireless camera in a capsule.","GI Evaluation lecture, slide 17");
T("GI evaluation",1,"Which procedure visualizes the rectum, sigmoid colon and part of the left colon only?","Flexible sigmoidoscopy",["Colonoscopy","Esophagogastroduodenoscopy","Capsule endoscopy"],"Colonoscopy views the whole large intestine. Flexible sigmoidoscopy covers only the distal portion.","GI Evaluation lecture, slide 17");
T("GI evaluation",2,"Which test is the gold standard for evaluating GERD?","24-hour ambulatory esophageal pH monitoring (pH below 4)",["Plain abdominal film with barium swallow and fluoroscopy","Fecal calprotectin measurement","Colonoscopy with biopsy"],"A trans-nasal probe is placed 5 cm above the lower esophageal sphincter and measures how long pH stays below 4.","GI Evaluation lecture, slide 23");
T("GI evaluation",3,"Which test can tell acid reflux from non-acid reflux in a patient who does not respond to acid suppression?","Multichannel intraluminal impedance combined with pH testing",["Upper GI series with small bowel follow-through","Flexible sigmoidoscopy","Transabdominal ultrasound"],"Impedance with manometry-type catheters detects both acid and non-acid reflux, so it is used when PPIs fail.","GI Evaluation lecture, slide 23");

/* ---------- Colonoscopy bowel preparation ---------- */
T("Bowel preparation",2,"Which bowel preparation is the preferred iso-osmotic option for patients with advanced liver disease, heart failure or IBD?","PEG-based products (for example GoLYTELY or MoviPrep)",["Sodium picosulfate/magnesium citrate (Clenpiq)","Sodium sulfate/potassium sulfate/magnesium sulfate (Suprep)","Sodium sulfate, magnesium sulfate and potassium chloride tablets (Sutab)"],"PEG preps are iso-osmotic with fewer fluid and electrolyte shifts. The hyperosmotic products carry a greater risk of dehydration and electrolyte problems.","GI Evaluation lecture, slide 22");
T("Bowel preparation",2,"Which bowel prep has the lowest volume but the highest osmolarity and should be avoided in heart failure, renal impairment and elderly patients?","Clenpiq (sodium picosulfate, magnesium citrate)",["GoLYTELY (4 L PEG-ELS, a large volume prep with no sugar)","NuLYTELY (sulfate-free PEG)","Plenvu (PEG with ascorbate)"],"Clenpiq is only about 0.35 L but is hyperosmotic, so it has the greatest risk of electrolyte imbalance and dehydration.","GI Evaluation lecture, slide 22");
T("Bowel preparation",3,"Which patient should avoid Suprep (sodium, potassium and magnesium sulfate)?","A patient with renal failure or gout",["A patient who cannot tolerate large-volume PEG because of taste","A patient with normal renal function who prefers a split dose","A healthy 50-year-old having a screening colonoscopy"],"Suprep is hyperosmotic, with more electrolyte disturbance than MoviPrep, so it is avoided in renal failure and gout.","GI Evaluation lecture, slide 22");
T("Bowel preparation",2,"Which bowel prep is a good alternative for a patient who cannot tolerate the taste of liquid preps?","Sutab tablets",["GoLYTELY","NuLYTELY","PEG with Gatorade"],"Sutab is 12 tablets taken with water. It contains the same sulfate salts as Suprep, so the same hyperosmotic precautions apply.","GI Evaluation lecture, slide 22");
T("Bowel preparation",2,"Which risk is specific to a homemade prep of Miralax (PEG) mixed in Gatorade?","Hyponatremia, so avoid it in heart failure and cirrhosis",["Hypercalcemia, so avoid it in hyperparathyroidism","QT prolongation, so avoid it with antiarrhythmics","Lactic acidosis, so avoid it in renal impairment"],"It is not as effective as prescription products. Large fluid volumes without electrolyte balance can cause hyponatremia.","GI Evaluation lecture, slide 22");
T("Bowel preparation",2,"Which bowel prep dosing approach is preferred?","Split dosing, with the last dose 4 to 6 hours before the procedure",["The whole dose the night before the procedure, finished by 8 PM","The whole dose 1 hour before the procedure","One large dose two days before the procedure"],"Split dosing flushes the secretions that accumulate overnight and gives a cleaner colon. 2 L products are suggested over 4 L products for better tolerance.","GI Evaluation lecture, slide 19");
T("Bowel preparation",2,"When are PEG-based bowel preps contraindicated?","GI obstruction",["Inflammatory bowel disease","Heart failure","Cirrhosis"],"Any prep that is given to flush the colon is dangerous with an obstruction. PEG is actually the preferred class in IBD, heart failure and advanced liver disease.","GI Evaluation lecture, slide 22");

/* ---------- IBD: UC versus Crohn's ---------- */
T("IBD: UC vs Crohn's",1,"Which finding is most characteristic of Crohn's disease rather than ulcerative colitis?","Transmural inflammation with skip lesions and a cobblestone appearance",["Continuous inflammation starting at the rectum","Inflammation limited to the mucosa and submucosa","Rectal bleeding in about 90% of patients"],"Crohn's can affect any part of the GI tract and goes through the whole bowel wall. UC is continuous, starts in the rectum and stays in the mucosa/submucosa.","IBD lecture, slide 12");
T("IBD: UC vs Crohn's",1,"Which feature is more typical of ulcerative colitis than Crohn's disease?","Continuous colonic lesions with common rectal bleeding",["Fistulas","Malabsorption","Very common ileal involvement with skip lesions throughout the bowel"],"UC causes a large increase in stool number and frequent rectal bleeding. Fistulas, malabsorption and ileal disease point to Crohn's.","IBD lecture, slides 11, 12");
T("IBD: UC vs Crohn's",2,"A patient has perianal fistulas and abscesses with abdominal pain and malabsorption. Which diagnosis is most likely?","Crohn's disease",["Ulcerative colitis","Irritable bowel syndrome","Ulcerative proctitis"],"Transmural inflammation leads to fistulas, abscesses and strictures. Malabsorption occurs in Crohn's but not UC.","IBD lecture, slides 11, 13");
T("IBD: UC vs Crohn's",2,"Which pairing of intestinal complication and disease is correct?","Toxic megacolon and colorectal cancer in UC; strictures and fistulas in Crohn's",["Toxic megacolon in Crohn's; strictures and fistulas in UC","Fistulas in UC; colorectal cancer risk only in Crohn's","Strictures in UC; toxic megacolon in Crohn's"],"Toxic megacolon carries about 50% mortality, and colorectal cancer causes 10 to 15% of UC deaths. Crohn's can also raise cancer risk, but less than UC.","IBD lecture, slide 17");
T("IBD: UC vs Crohn's",2,"How does active smoking affect IBD?","It worsens Crohn's disease and can cause flares, but may improve ulcerative colitis",["It improves Crohn's disease and worsens ulcerative colitis","It worsens both diseases equally","It improves both diseases"],"Smoking raises surgery, hospitalization and penetrating disease in Crohn's. A nicotine patch is not typically recommended for UC despite limited evidence of benefit.","IBD lecture, slide 16");
T("IBD: UC vs Crohn's",3,"Which immune pattern is associated with Crohn's disease versus ulcerative colitis?","Crohn's: Th1 and Th17 excess; UC: Th2 excess",["Crohn's: Th2 excess; UC: Th1 and Th17 excess","Both are driven only by Th2 cells","Both are driven only by B cells"],"IBD is multifactorial (gut flora, immune dysfunction, environment and genetics). Genetics matter more in Crohn's than in UC.","IBD lecture, slide 15");
T("IBD: UC vs Crohn's",2,"Which extraintestinal problem is more common in Crohn's disease and can also result from long-term corticosteroids?","Osteoporosis",["Hyperthyroidism","Hyperkalemia","Gout"],"Extraintestinal manifestations are more common in Crohn's. Bone loss comes from inflammation and from steroid use.","IBD lecture, slide 18");
T("IBD: UC vs Crohn's",2,"Which statement about the location of disease is correct?","UC begins in the rectum and extends continuously; Crohn's can occur anywhere from the mouth to the anus, often in the ileum",["UC commonly involves the ileum and Crohn's never involves the colon","Crohn's is limited to the rectum","UC skips areas of normal bowel"],"UC is limited to the colon. About 20% of Crohn's patients see their disease extend over time, such as ileal disease becoming ileocolonic.","IBD lecture, slides 9, 12");
T("IBD: UC vs Crohn's",2,"Which test helps separate IBD from irritable bowel syndrome and can be used to monitor disease?","Fecal calprotectin",["Hemoglobin A1c measured after an overnight fast","Serum amylase","Urinalysis"],"Calprotectin comes from white blood cells and rises with bowel inflammation but not in functional IBS. ESR and CRP also reflect inflammation in some patients.","IBD lecture, slide 19");
T("IBD: UC vs Crohn's",1,"What should be excluded before a patient is diagnosed with IBD?","Infectious causes such as C. difficile",["Hypothyroidism with a high TSH and low free T4","Peptic ulcer disease","Gallstones"],"Infectious diarrhea and C. diff can mimic IBD. The work-up then uses colonoscopy with biopsy, with imaging for small bowel disease.","IBD lecture, slide 19");

/* ---------- IBD: treatment goals and definitions ---------- */
T("IBD: treatment goals",2,"Which term describes a patient who is symptom-free on daily prednisone but whose symptoms return when the steroid is removed?","Steroid dependence",["Steroid-free remission","Mucosal remission","Treatment response"],"Steroid-free remission means remission achieved with non-steroid drugs. Steroid-dependent patients need an immunomodulator or biologic added.","IBD lecture, slides 23, 44");
T("IBD: treatment goals",1,"Which is a goal of IBD therapy?","Induce and maintain remission while avoiding surgery and minimizing steroid exposure",["Cure the disease with a short course of steroids","Use steroids for long-term maintenance","Treat symptoms only and ignore mucosal healing"],"Endoscopic (mucosal) changes matter as well as symptoms. Steroids are only for induction because of their adverse effects.","IBD lecture, slide 24");

/* ---------- IBD: 5-aminosalicylates ---------- */
T("IBD: 5-ASA",1,"For which disease are all 5-aminosalicylates indicated in mild to moderate disease?","Ulcerative colitis",["Crohn's disease","Both conditions equally","Neither; they are reserved for severe disease"],"Only sulfasalazine has evidence in mild Crohn's, mostly for colonic symptom relief.","IBD lecture, slides 33, 36");
T("IBD: 5-ASA",2,"Which 5-ASA product has evidence for mild Crohn's disease?","Sulfasalazine",["Mesalamine","Balsalazide","Olsalazine, which is an azo-bonded 5-ASA dimer"],"Other 5-ASAs are not recommended for Crohn's. Sulfasalazine also has the most adverse effects of the class.","IBD lecture, slides 33, 36");
T("IBD: 5-ASA",2,"Which supplement should accompany sulfasalazine?","Folic acid",["Vitamin K to protect against bleeding from the drug","Iron","Vitamin D"],"Sulfasalazine causes folate deficiency. Avoid it in patients with sulfonamide or aspirin allergy.","IBD lecture, slide 39");
T("IBD: 5-ASA",2,"Why is mesalamine usually first line for mild to moderate UC while sulfasalazine is second line?","Mesalamine products are best tolerated, whereas sulfasalazine has the most adverse effects",["Sulfasalazine is not effective in UC","Mesalamine is cheaper than sulfasalazine","Mesalamine works systemically while sulfasalazine does not"],"Mesalamine is better tolerated but more expensive. Balsalazide and olsalazine are well tolerated but may cause more osmotic, watery diarrhea.","IBD lecture, slide 39");
T("IBD: 5-ASA",2,"Which mesalamine formulation is best for isolated proctitis?","Rectal suppository",["Rectal enema","Delayed-release oral capsule alone","IV infusion"],"Suppositories reach the rectum. Enemas reach the left colon, and oral products treat left-sided or extensive colitis.","IBD lecture, slide 34");
T("IBD: 5-ASA",2,"Which mesalamine formulation is best for left-sided ulcerative colitis?","Rectal enema, with or without an oral product",["Rectal suppository alone","IV methylprednisolone","Oral azathioprine started at full dose for fast control"],"The enema reaches the left colon. Combining topical and oral mesalamine is more effective than either alone.","IBD lecture, slide 34");
T("IBD: 5-ASA",3,"A patient with mild to moderate UC has not responded to an adequate dose of oral mesalamine. What is the best next step?","Optimize the dose or add rectal 5-ASA; switching to another 5-ASA product offers no benefit",["Switch to another oral 5-ASA product at the same dose","Start long-term prednisone for maintenance","Add azathioprine for fast induction"],"Oral products differ by site of release, not by efficacy. Increase the dose (typically to 4.8 g/day for moderate disease) or add rectal therapy.","IBD lecture, slides 35, 37");
T("IBD: 5-ASA",2,"How long should a 5-ASA enema be retained?","At least 1 hour and ideally 8 hours, given at bedtime",["Only 5 minutes, then it should be washed out with water","Until the next meal","It is swallowed rather than retained"],"Enemas are 4 g at bedtime and suppositories are 1 g at bedtime. Longer retention improves local effect.","IBD lecture, slide 37");

/* ---------- IBD: corticosteroids ---------- */
T("IBD: corticosteroids",1,"What is the role of corticosteroids in IBD?","Induction of remission, not maintenance",["Long-term maintenance of remission","Healing fistulas and abscesses","Preventing relapse after surgery for up to 2 years"],"Steroids work quickly (70 to 80% symptomatic remission in Crohn's at 8 weeks) but do not heal the mucosa or treat fistulas, and the adverse effects limit long-term use.","IBD lecture, slide 40");
T("IBD: corticosteroids",2,"Which budesonide product is used for ileal or right-sided Crohn's disease?","Entocort (delayed-release, releases in the ileum)",["Uceris (extended-release, releases in the colon)","Inhaled budesonide","Budesonide IV"],"The oral budesonide formulations are not the inhaled product. Entocort releases in the ileum and right colon.","IBD lecture, slide 45");
T("IBD: corticosteroids",2,"Which budesonide product is used for ulcerative colitis or colonic Crohn's disease?","Uceris (extended-release, releases in the colon)",["Entocort (delayed-release, releases in the ileum)","Inhaled budesonide","Budesonide IV"],"Rectal budesonide foam is used only for left-sided UC.","IBD lecture, slides 2, 43, 45");
T("IBD: corticosteroids",2,"Why does budesonide cause fewer systemic adverse effects than prednisone?","Extensive first-pass metabolism (10 to 13% bioavailable) limits systemic exposure",["It is not absorbed through the gut at all","It has no glucocorticoid activity","It is given only intravenously"],"Budesonide acts as a local steroid in the GI tract, so it is better tolerated but less effective than prednisone for moderate to severe disease.","IBD lecture, slide 45");
T("IBD: corticosteroids",3,"A patient with fulminant UC needs hospitalization. Which steroid regimen is appropriate?","IV methylprednisolone 40 to 60 mg daily or IV hydrocortisone 100 mg three times daily",["Oral budesonide 9 mg daily","Rectal budesonide foam 2 mg twice daily","Oral mesalamine 2.4 g daily"],"Oral prednisone 40 to 60 mg daily is used for outpatient moderate to severe disease. Budesonide is for mild to moderate disease.","IBD lecture, slide 43");
T("IBD: corticosteroids",2,"Why must IBD steroid courses be tapered?","To avoid adrenal suppression and steroid withdrawal symptoms",["To prevent angioedema when the dose falls","To avoid hyperkalemia and fluid loss as the dose falls","To prevent pancreatitis during the taper"],"Tapers should be completed in under 3 months. If symptoms return when the dose is lowered, add an immunomodulator or biologic.","IBD lecture, slide 44");
T("IBD: corticosteroids",2,"Which long-term corticosteroid effects limit their use in IBD?","Osteoporosis, cataracts, infection and hyperglycemia",["Pancreatitis, myelosuppression and lymphoma","Heart block, QT prolongation and bradycardia","Hyperkalemia, angioedema and cough"],"Short-term effects include fluid retention, high BP, mood changes, insomnia and increased appetite.","IBD lecture, slide 42");

/* ---------- IBD: immunomodulators ---------- */
T("IBD: immunomodulators",2,"What is the main role of azathioprine and 6-mercaptopurine in IBD?","Maintenance of remission (slow onset of 2 to 3 months), not induction",["Rapid induction of remission","Treating acute toxic megacolon","Healing proctitis topically"],"They are older, cheaper drugs used in steroid-dependent patients, in patients who start steroids with a severe presentation, and combined with infliximab.","IBD lecture, slide 47");
T("IBD: immunomodulators",2,"What should be checked before starting azathioprine or 6-mercaptopurine?","TPMT enzyme activity",["CYP2D6 genotype and a baseline serum creatinine","HLA-B*5701","G6PD only"],"Poor TPMT metabolizers (about 0.3% of patients) have severe myelosuppression.","IBD lecture, slide 49");
T("IBD: immunomodulators",2,"Which immunomodulator is limited to Crohn's disease?","Methotrexate",["Azathioprine","6-Mercaptopurine","Both azathioprine and 6-mercaptopurine"],"The thiopurines are oral agents used in both CD and UC. Methotrexate can be oral or injectable.","IBD lecture, slide 46");
T("IBD: immunomodulators",3,"Which adverse effect of a thiopurine is dose related and managed by reducing the dose rather than stopping?","Myelosuppression",["Pancreatitis","Fever and rash that appears within the first few weeks","Arthralgia"],"Idiosyncratic reactions (pancreatitis, fever, rash, arthralgia) mean discontinue the drug. Long-term use also raises lymphoma and skin cancer risk.","IBD lecture, slide 49");
T("IBD: immunomodulators",3,"Why is a thiopurine often combined with infliximab?","It lowers anti-drug antibody formation and improves steroid-free remission",["It replaces the need for the infliximab loading doses","It prevents infusion-site infection","It makes infliximab work faster than 2 weeks"],"In the SONIC trial, antibodies to infliximab occurred in 14.6% with infliximab alone versus 0.9% with combination therapy.","IBD lecture, slides 47, 48");

/* ---------- IBD: biologics and small molecules ---------- */
T("IBD: biologics",2,"Which Janus kinase inhibitor can be used for both Crohn's disease and ulcerative colitis?","Upadacitinib",["Tofacitinib, which is approved only for ulcerative colitis","Ozanimod","Etrasimod"],"Tofacitinib is limited to UC. Both JAK inhibitors carry the same FDA warnings.","IBD lecture, slides 50, 68");
T("IBD: biologics",2,"Which therapy is generally the first choice for moderate to severe UC or Crohn's, often with a thiopurine?","Infliximab, with or without a thiopurine",["Tofacitinib as monotherapy","Ozanimod as monotherapy","Oral budesonide as maintenance"],"Anti-TNF drugs are used for both induction and maintenance and are very effective for fistulizing Crohn's disease.","IBD lecture, slide 71");
T("IBD: biologics",2,"What is the standard infliximab induction regimen in IBD?","5 mg/kg IV at weeks 0, 2 and 6, then every 8 weeks",["40 mg every 2 weeks from day 1","160 mg then 80 mg then 40 mg every 2 weeks","10 mg twice daily by mouth for 8 weeks, then stop"],"The adalimumab regimen is 160 mg, then 80 mg 2 weeks later, then 40 mg every 2 weeks starting day 29.","IBD lecture, slide 54");
T("IBD: biologics",3,"A patient on infliximab loses response and drug levels are low with high anti-drug antibodies. Which approach is reasonable?","Use a different class, or a different anti-TNF (not an infliximab biosimilar)",["Switch to a biosimilar of the same infliximab","Add long-term prednisone to the infliximab","Stop all therapy and observe"],"If efficacy is lost to the parent drug, do not switch to its biosimilar. Using a different class is usually more effective.","IBD lecture, slides 55, 58, 71");
T("IBD: biologics",2,"Which is a major adverse effect concern with TNF-alpha inhibitors?","Serious infections such as tuberculosis, plus lymphoma and skin cancer",["Hyperkalemia and renal artery stenosis from RAAS blockade","Pancreatitis and myelosuppression from purine antagonism","Gynecomastia and hyperkalemia from aldosterone blockade"],"Use caution in heart failure. Paradoxical psoriasis-like skin reactions and infusion reactions related to antibodies can also occur.","IBD lecture, slide 57");
T("IBD: biologics",3,"What makes vedolizumab more gut-specific than other immune response modifiers?","It blocks alpha4-beta7 integrin binding to MAdCAM-1 on gut vessels",["It inhibits TNF-alpha throughout the whole body and gut","It blocks Janus kinase signaling inside cells","It traps lymphocytes in the lymph nodes"],"It blocks T-cell migration into the intestinal tissue. Onset is slower than anti-TNF drugs, and it may not be best if extraintestinal manifestations are present.","IBD lecture, slide 61");
T("IBD: biologics",2,"Which agent inhibits both IL-12 and IL-23 and is a good second option in UC after anti-TNF failure?","Ustekinumab",["Vedolizumab","Tofacitinib","Ozanimod"],"IV weight-based induction is followed by subcutaneous maintenance every 8 weeks. Risankizumab inhibits IL-23 only.","IBD lecture, slide 64");
T("IBD: biologics",3,"Why is tofacitinib not used as a first agent in UC?","Boxed warnings for infections (herpes zoster), clots, cancer and death",["It is only effective in Crohn's disease","It must always be combined with azathioprine to work at all","It cannot be taken by mouth"],"It is UC only and considered a second option after anti-TNF failure. Do not combine it with azathioprine or 6-MP, and vaccinate against zoster.","IBD lecture, slide 67");
T("IBD: biologics",2,"Which drugs have fewer infectious complications than anti-TNF therapy?","Vedolizumab and risankizumab",["Tofacitinib and upadacitinib","Infliximab and adalimumab","Azathioprine and methotrexate"],"JAK inhibitors are reserved as later-line agents because of their safety warnings.","IBD lecture, slide 71");
T("IBD: biologics",3,"Which oral agents act as sphingosine-1-phosphate receptor modulators that keep lymphocytes in lymph nodes?","Ozanimod and etrasimod (UC)",["Tofacitinib and upadacitinib","Vedolizumab and ustekinumab","Infliximab and adalimumab"],"They may be more effective in moderate than severe disease.","IBD lecture, slides 50, 70");
T("IBD: biologics",3,"Which biosimilar statement is correct?","If efficacy is lost with the parent biologic, do not switch to its biosimilar",["Any biosimilar can be substituted without a prescription","Biosimilars have no clinical trial data","Biosimilars have worse adverse effect profiles"],"Interchangeable biosimilars can be substituted without a new prescription if state law allows. Adalimumab has several interchangeable products and infliximab has biosimilars.","IBD lecture, slide 58");

/* ---------- IBD: vaccines and surgery ---------- */
T("IBD: vaccines",2,"When should inactivated vaccines be given to a patient about to start a biologic?","At least 2 weeks before starting if possible",["Only after 1 year of therapy","Never; they are contraindicated","On the same day as the first biologic dose, never earlier"],"Responses to vaccines can be blunted on biologics, so extra doses may be needed.","IBD lecture, slide 73");
T("IBD: vaccines",2,"What is the timing rule for live vaccines with biologics?","1 month before or 3 months after a biologic (1 month after oral agents)",["At any time, since live vaccines are safe on biologics","2 weeks before and 2 weeks after any biologic dose","6 weeks before and 6 weeks after any biologic dose"],"Live vaccines are contraindicated with immune response therapy or high-dose steroids.","IBD lecture, slide 73");
T("IBD: vaccines",3,"Which biologic is the exception where a live vaccine may be used if benefit outweighs risk?","Vedolizumab",["Infliximab","Adalimumab","Ustekinumab"],"Vedolizumab appears to blunt only oral vaccines because it is gut-specific.","IBD lecture, slide 73");
T("IBD: vaccines",3,"Why should aminosalicylates be delayed for 6 weeks after a varicella vaccine in children?","Risk of Reye's syndrome",["Risk of angioedema","Risk of pancreatitis","Risk of vaccine failure only"],"Aspirin-like salicylates are linked to Reye's syndrome after varicella infection or vaccination.","IBD lecture, slide 73");
T("IBD: surgery",2,"Which statement about surgery in IBD is correct?","Total colectomy is curative in UC, while surgery in Crohn's provides temporary relief and disease can recur",["Surgery is curative in Crohn's disease","Surgery is never used in UC","Surgery is performed in most UC patients but in few Crohn's patients"],"Roughly 20 to 30% of UC and 80% of Crohn's patients eventually need surgery. Crohn's recurrence can reach 70% mucosally in one year.","IBD lecture, slide 74");

/* ---------- Peptic ulcer disease (Overview of Peptic Ulcer Disease lecture, 2026) ---------- */
const PUL = "Peptic Ulcer Disease lecture";
T("PUD: GERD vs ulcers",1,"Which symptom pattern points to GERD rather than a gastroduodenal ulcer?","Substernal burning with acid regurgitation into the throat",["Epigastric pain with early satiety","Postprandial fullness and bloating with early satiety","Epigastric burning in the upper abdomen"],"Heartburn (substernal burning, regurgitation, trouble swallowing) comes from acid refluxing into the esophagus. Epigastric pain, fullness and early satiety (dyspepsia) fit ulcers.",PUL+", slide 9");
T("PUD: GERD vs ulcers",1,"Which symptom is more typical of a gastroduodenal ulcer than of GERD?","Early satiety",["Regurgitation of acid into the throat","Difficulty swallowing","Substernal burning"],"Dyspepsia (epigastric pain or burning, postprandial fullness, bloating, early satiety) is linked to ulcers. Substernal burning, regurgitation and trouble swallowing are the reflux pattern. Some overlap can occur.",PUL+", slide 9");
T("PUD: GERD vs ulcers",1,"Dyspepsia is most associated with which condition?","Gastroduodenal ulcers",["GERD","Esophageal strictures","Gastroparesis"],"Heartburn goes with acid reflux (GERD). Dyspepsia, meaning upper abdominal pain, fullness and early satiety, goes with gastroduodenal ulcers.",PUL+", slide 9");
T("PUD: GERD vs ulcers",2,"Why does acid damage the esophagus in GERD?","The esophageal lining has little protection against acid that refluxes up",["H. pylori lowers bicarbonate secretion in the esophagus","NSAIDs loosen the tight junctions of esophageal cells and thin the mucus layer","The esophagus makes too little pepsin to digest food"],"In GERD, acid inappropriately refluxes up and erodes an epithelium that has little acid protection. Ulcers are different: the stomach or duodenal defenses are weakened first.",PUL+", slide 8");
T("PUD: GERD vs ulcers",2,"What drives a gastroduodenal ulcer but is NOT the main problem in GERD?","H. pylori, NSAIDs or ischemia weakening the mucosal defenses",["Acid refluxing up into the esophagus","An esophageal lining with little acid protection","Stomach contents moving back into the throat"],"In ulcers, outside factors reduce bicarbonate secretion, loosen tight junctions and slow epithelial repair, so acid reaches the submucosa. GERD is a reflux problem.",PUL+", slide 8");
T("PUD: GERD vs ulcers",1,"A peptic ulcer is an erosion of the mucosa larger than what size that goes deeper into the muscularis mucosa?","5 mm",["1 mm","2 cm","1 inch"],"Gastritis or duodenitis is inflammation that erodes the lining. A peptic ulcer is a deeper erosion, larger than 5 mm, related to stomach acid.",PUL+", slide 6");
T("PUD: acid suppression",1,"Which drug protects the stomach lining without mainly raising stomach pH?","Sucralfate",["Famotidine","Vonoprazan","Sodium bicarbonate"],"The protectors are sucralfate, misoprostol and bismuth. Vonoprazan, PPIs, H2 blockers and antacids raise pH.",PUL+", slide 10");
T("PUD: PPIs",1,"Why are PPIs given as delayed release products?","They are broken down by stomach acid",["They irritate the esophagus if released early","They bind food in the stomach","They only work after leaving the liver"],"PPIs are acid labile, so a delayed release coating protects them from stomach acid.",PUL+", slide 13");
T("PUD: PPIs",1,"When is a standard PPI best taken?","30 to 60 minutes before a meal",["At bedtime only","With the first bite of food, as with a short-acting H2 blocker","30 minutes after a meal"],"PPIs block only active pumps. Taking one before the meal gives the highest drug level when the pumps are mobilized by eating.",PUL+", slide 13");
T("PUD: PPIs",2,"Which PPI does not need to be taken before food and is indicated only for GERD?","Dexlansoprazole",["Esomeprazole","Pantoprazole delayed-release tablets taken with a meal","Rabeprazole"],"Dexlansoprazole has a continuous (extended) release mechanism, so timing around meals matters less. It is not indicated for ulcers.",PUL+", slides 13, 14");
T("PUD: PPIs",2,"How do PPIs block acid?","They irreversibly inhibit the active H+/K+ ATPase proton pump",["They block histamine type 2 receptors on parietal cells","They neutralize acid already in the stomach","They coat the ulcer base"],"PPIs bind active pumps for good, and the body has to make new pumps.",PUL+", slide 13");
T("PUD: PPIs",2,"Which PPI is available as an oral disintegrating tablet?","Lansoprazole",["Omeprazole","Pantoprazole","Rabeprazole"],"Lansoprazole is the PPI with a dissolving (oral disintegrating) tablet. Pantoprazole and rabeprazole are tablets only.",PUL+", slide 15");
T("PUD: PPIs",2,"Which PPI is the commonly used IV option in the US?","Pantoprazole",["Omeprazole","Lansoprazole","Rabeprazole"],"Pantoprazole is the usual IV PPI. Esomeprazole IV is uncommon, and omeprazole IV is not available in the US.",PUL+", slide 15");
T("PUD: PPIs",3,"Which statement about IV PPIs is correct?","Pantoprazole is the usual IV choice and esomeprazole IV is uncommon",["Omeprazole IV is the first choice in the US","Rabeprazole is the usual IV choice for bleeding ulcers in the US","Dexlansoprazole IV is used for bleeding ulcers"],"Pantoprazole is the standard IV PPI. Esomeprazole IV exists but is uncommon. Omeprazole IV is not available in the US.",PUL+", slide 15");
T("PUD: PPIs",2,"Which two PPIs are prescription only?","Pantoprazole and rabeprazole",["Omeprazole and esomeprazole","Lansoprazole and omeprazole","Esomeprazole and lansoprazole"],"Protonix (pantoprazole) and Aciphex (rabeprazole) are Rx only. Omeprazole, esomeprazole and lansoprazole all have OTC strengths.",PUL+", slides 14, 16");
T("PUD: PPIs",2,"Which Rx only PPI is noted for having fewer drug interactions?","Pantoprazole",["Omeprazole","Esomeprazole","Lansoprazole"],"Protonix (pantoprazole) is prescription only and has fewer drug-drug interactions than omeprazole-type PPIs.",PUL+", slide 14");
T("PUD: PPIs",3,"Which Rx only PPI does not rely on CYP2C19 metabolism?","Rabeprazole",["Omeprazole","Esomeprazole","Lansoprazole"],"Aciphex (rabeprazole) is prescription only and does not rely on CYP2C19.",PUL+", slide 14");
T("PUD: PPIs",2,"Which PPI packet for oral suspension is made with sodium bicarbonate?","Omeprazole",["Lansoprazole","Pantoprazole","Rabeprazole"],"The omeprazole packet contains bicarbonate to protect it from acid. Esomeprazole also comes as a packet, without the bicarbonate note.",PUL+", slide 15");
T("PUD: PPIs",3,"Which PPI capsule can be opened in water, only for immediate use through a nasogastric tube?","Esomeprazole",["Omeprazole","Lansoprazole","Dexlansoprazole"],"Esomeprazole is the one marked as OK to open in water, and only for immediate administration in an NG tube. Others use applesauce or juice.",PUL+", slide 15");
T("PUD: PPIs",1,"Zegerid contains omeprazole plus what?","An antacid (sodium bicarbonate)",["Famotidine","Sucralfate, which coats the ulcer base","Bismuth"],"Zegerid is omeprazole with an antacid, which helps protect the drug from stomach acid.",PUL+", slides 14, 15");
T("PUD: PPIs",1,"Nexium (esomeprazole) is which form of omeprazole?","The S-isomer",["The R-isomer","A calcium salt","A prodrug of lansoprazole"],"Esomeprazole is the S-isomer of omeprazole.",PUL+", slide 14");
T("PUD: PPIs",1,"How do prescription PPI doses compare with OTC doses?","Prescription doses are up to twice the OTC strength",["They are ten times the OTC dose in every case","They are the same","Prescription doses are half the OTC dose"],"OTC PPIs are lower strength, used for 14-day courses of frequent heartburn.",PUL+", slide 16");
T("PUD: PPIs",2,"Which two PPIs are considered more potent if the first PPI does not work?","Omeprazole and rabeprazole",["Pantoprazole and lansoprazole","Dexlansoprazole and pantoprazole","Lansoprazole and dexlansoprazole"],"There are no real differences between PPIs in ulcer healing, and none is preferred in GERD. If the first is inadequate, switching to omeprazole or rabeprazole is an option.",PUL+", slide 17");
T("PUD: PPIs",2,"Which statement about PPI efficacy is correct?","No PPI is preferred for ulcer healing or GERD",["Pantoprazole heals ulcers faster than all other PPIs","Esomeprazole is the only PPI that works for GERD","Lansoprazole is the only PPI that heals ulcers"],"There are no real differences between PPIs for ulcer healing, and no PPI is preferred in GERD.",PUL+", slide 17");
T("PUD: PPIs",2,"How can acid suppression with a PPI be improved?","Twice-daily dosing or double doses",["Taking it after meals","Taking it only at bedtime with a large snack","Crushing the tablet"],"Twice-daily or double doses improve acid suppression. PPIs raise pH more than H2 blockers but less than vonoprazan.",PUL+", slide 17");
T("PUD: vonoprazan",2,"How does vonoprazan differ from a PPI?","It is acid stable and does not need acid to be activated",["It irreversibly binds only inactive pumps","It must be given 30 to 60 minutes before meals","It needs an enteric delayed-release coating to survive stomach acid"],"Vonoprazan is acid stable, binds pumps in the cytoplasm (reversibly but with high affinity) and can be given without regard to food.",PUL+", slide 19");
T("PUD: vonoprazan",2,"Which acid suppressant is the most effective and longest lasting?","Vonoprazan",["Omeprazole","Famotidine","Calcium carbonate"],"Vonoprazan (Voquezna, approved 2022) competes with potassium at the H+/K+ ATPase and is the most effective acid suppressant.",PUL+", slide 19");
T("PUD: vonoprazan",2,"How long does vonoprazan take to reach its maximum effect compared with PPIs?","About 1 day, versus about 3 days for PPIs",["About 3 days, versus 1 day for PPIs","About 1 hour, versus 1 day for PPIs","Both take about 1 week"],"Vonoprazan reaches maximum effect faster than PPIs.",PUL+", slide 27");
T("PUD: H2RAs",1,"Which H2 blocker comes in an IV form?","Famotidine",["Nizatidine","Sucralfate","Misoprostol"],"Famotidine (Pepcid) comes as a tablet, suspension and IV. Nizatidine is a capsule. Sucralfate and misoprostol are oral.",PUL+", slide 22");
T("PUD: H2RAs",2,"What is the best timing for an H2 blocker once-daily dose?","At bedtime",["Right after breakfast","With the largest meal","Only when symptoms start"],"H2 blockers work best as a once-daily bedtime dose.",PUL+", slide 21");
T("PUD: H2RAs",2,"What happens if an H2 blocker is taken on a schedule for 1 to 2 weeks?","Tachyphylaxis (tolerance) can develop",["Rebound ulcers always form once the drug is stopped","The drug becomes irreversible","Gastrin falls to zero"],"The effect fades with repeated scheduled use.",PUL+", slide 21");
T("PUD: H2RAs",2,"Which H2 blocker causes gynecomastia and impotence and has the most drug interactions?","Cimetidine",["Famotidine","Nizatidine","Ranitidine"],"Cimetidine inhibits CYP450, interacting with warfarin, phenytoin, theophylline, carbamazepine and beta blockers.",PUL+", slide 23");
T("PUD: H2RAs",2,"How should H2 blocker doses be changed in kidney impairment?","Reduce the dose by 50%",["Double the dose, since the kidneys clear it faster","No change is needed","Give only IV"],"Rare CNS effects such as confusion can occur with IV famotidine in elderly patients with renal impairment.",PUL+", slide 23");
T("PUD: antacids",1,"Which acid-reducing option has the fastest onset?","Antacids",["Famotidine","Omeprazole","Vonoprazan"],"Antacids work in less than 5 minutes, but only last 20 to 30 minutes. They are for quick symptom relief, not ulcer treatment.",PUL+", slides 25, 27");
T("PUD: antacids",2,"What is the typical onset of relief for a PPI or vonoprazan?","2 to 3 hours",["Less than 5 minutes","30 to 45 minutes","12 to 24 hours"],"PPIs and vonoprazan take 2 to 3 hours to relieve symptoms but last 12 to 24 hours.",PUL+", slide 27");
T("PUD: antacids",2,"What are the onset and duration of relief for an H2 blocker?","Onset 30 to 45 minutes, lasting 4 to 10 hours",["Onset under 5 minutes, lasting 20 to 30 minutes","Onset 2 to 3 hours, lasting 12 to 24 hours","Onset 1 day, lasting 3 days"],"H2 blockers fall between antacids (fastest) and PPIs (longest).",PUL+", slide 27");
T("PUD: antacids",3,"A patient wants relief within minutes that also lasts through the night. Which option fits best?","An H2 blocker plus an antacid",["An antacid alone","A PPI alone taken at the time of symptoms","Sucralfate alone"],"H2 blocker plus antacid starts in under 5 minutes and lasts 8 to 10 hours. An antacid alone lasts only 20 to 30 minutes, and a PPI takes 2 to 3 hours.",PUL+", slide 27");
T("PUD: antacids",2,"How long does an antacid last on an empty stomach compared with after a meal?","15 to 30 minutes, versus 1 to 2 hours",["1 to 2 hours, versus 15 to 30 minutes","4 to 10 hours, versus 12 to 24 hours","30 to 45 minutes, versus 8 to 10 hours"],"Timing matters: after a meal the onset is slower but the effect lasts longer.",PUL+", slide 25");
T("PUD: antacids",2,"In a magnesium and aluminum antacid, which ingredient most often causes diarrhea?","Magnesium hydroxide",["Aluminum hydroxide","Sodium bicarbonate","Calcium carbonate, which is a common constipating antacid"],"Magnesium can cause diarrhea and aluminum can cause constipation. Usually diarrhea predominates.",PUL+", slide 26");
T("PUD: antacids",1,"Antacids are used for what in ulcer disease?","Fast symptom relief, not ulcer treatment",["Healing duodenal ulcers","Killing H. pylori","Preventing NSAID ulcers when taken every day for months"],"They neutralize acid for quick relief but are not used to treat ulcers.",PUL+", slide 25");
T("PUD: sucralfate",2,"For which ulcers is sucralfate FDA indicated?","Duodenal ulcers only",["Gastric ulcers only","Esophageal ulcers","Both gastric and duodenal ulcers"],"Sucralfate is prescription only. It binds exposed tissue in the presence of acid, so it is taken on an empty stomach.",PUL+", slide 28");
T("PUD: sucralfate",2,"How should sucralfate be separated from other drugs?","By 2 hours",["By 30 minutes","By 12 hours","It does not need separation"],"Sucralfate has the same binding interactions as aluminum, such as fluoroquinolones. It can also cause constipation (up to 9%).",PUL+", slide 28");
T("PUD: misoprostol",2,"What is misoprostol mainly used for in peptic disease?","Preventing NSAID-induced ulcers",["Treating an active ulcer","Eradicating H. pylori","Neutralizing acid"],"Misoprostol is a prostaglandin analog. It is as effective as a daily PPI for NSAID ulcer prevention but is rarely used because of side effects.",PUL+", slide 29");
T("PUD: misoprostol",2,"Which adverse effect is common with misoprostol at full dose?","Diarrhea",["Constipation","Gynecomastia","Hypermagnesemia"],"Misoprostol is not used for acute ulcer treatment.",PUL+", slide 29");

/* ---------- Hemorrhoids (Hemorrhoids lecture, 2026) ---------- */
const HRL = "Hemorrhoids lecture";
T("Hemorrhoids: basics",1,"What is a hemorrhoid?","An inflamed, swollen collection of veins in the anal canal",["A tear in the anal lining","A pocket of infection in the anal glands","A growth of abnormal anal cells"],"Hemorrhoids come from loss of connective tissue support, with veins that enlarge with straining and hard stools.",HRL+", slide 4");
T("Hemorrhoids: basics",1,"Which factor helps cause hemorrhoids?","Straining and passing hard stools",["Taking fiber each day","Drinking 6 to 8 glasses of water","Sitting for less than 2 minutes on the toilet"],"Loss of connective tissue support and straining enlarge the veins.",HRL+", slide 4");
T("Hemorrhoids: basics",2,"In which group are hemorrhoids especially common?","Pregnancy and after childbirth",["Teenagers","Patients taking fiber","Children under 5"],"Hemorrhoids occur in about 25% of pregnancies and about 85% after childbirth.",HRL+", slide 4");
T("Hemorrhoids: internal vs external",1,"Where are internal hemorrhoids located?","About 0.5 to 2 cm above the dentate line",["Below the dentate line","At the anal verge on the skin","In the sigmoid colon"],"External hemorrhoids lie below the dentate line, about 1 inch from the anal verge, where skin changes to mucosa.",HRL+", slides 5, 6");
T("Hemorrhoids: internal vs external",2,"Why are internal hemorrhoids usually painless?","Above the dentate line the nerves sense pressure and stretch, not sharp pain",["They have no blood supply","They have somatic pain nerves that are blocked","They only form in the elderly"],"Above the dentate line there is visceral innervation. Below it, somatic innervation carries pain, temperature and touch.",HRL+", slide 6");
T("Hemorrhoids: internal vs external",2,"Which blood supply drains the area above the dentate line?","The portal system",["The systemic system","The coronary system","The renal system"],"Below the dentate line the drainage is systemic, which is why rectal drugs below it bypass first-pass metabolism.",HRL+", slide 6");
T("Hemorrhoids: internal vs external",2,"Where is systemic drug absorption generally greater?","For drugs given above the dentate line",["For drugs given below the dentate line","It is the same both ways","Only for drugs on external skin"],"Above the dentate line drainage is portal, so absorption is greater. Below it drainage is systemic and bypasses first pass.",HRL+", slide 6");
T("Hemorrhoids: internal vs external",1,"Which finding fits an internal hemorrhoid?","Painless bright red blood on the outside of the stool",["Severe pain from a clot","Itching and burning when wiping","A black tarry stool"],"Internal hemorrhoids bleed with defecation and may prolapse.",HRL+", slide 7");
T("Hemorrhoids: internal vs external",1,"Which symptom fits an external hemorrhoid?","Itching, burning or pain when cleaning after a bowel movement",["Painless bright red blood on stool","Protrusion that goes back on its own","A dull ache from stretch only"],"External hemorrhoids have pain innervation. A clot (thrombosed) causes severe pain.",HRL+", slide 7");
T("Hemorrhoids: internal vs external",2,"A patient has sudden severe pain and a hard lump at the anus. What is the best next step?","Refer to a prescriber because a thrombosed hemorrhoid is a self-treatment exclusion",["Recommend an OTC suppository","Start a stimulant laxative","Reassure and recheck in 2 weeks"],"Acute onset of severe pain, thrombosis, bleeding, seepage and prolapse all need referral.",HRL+", slides 7, 10");
T("Hemorrhoids: internal vs external",1,"Which dosage forms are used for internal hemorrhoids?","Suppositories and ointments",["Sprays and wipes","Creams, sprays and wipes","Sitz baths only"],"External hemorrhoids use ointments, creams, sprays and wipes.",HRL+", slide 8");
T("Hemorrhoids: internal vs external",1,"Which dosage forms are used only for external hemorrhoids?","Creams, sprays and wipes",["Suppositories","Ointments with applicators","Rectal enemas"],"Ointments can be used for both. Suppositories are for internal hemorrhoids.",HRL+", slide 8");
T("Hemorrhoids: grades",2,"Which grade of internal hemorrhoid protrudes past the anal canal and needs to be pushed back in by hand?","Grade 3",["Grade 1","Grade 2","Grade 4"],"Grade 1 may bleed but does not prolapse. Grade 2 reduces on its own. Grade 3 needs manual reduction. Grade 4 cannot be reduced.",HRL+", slide 9");
T("Hemorrhoids: grades",2,"Which grade protrudes during defecation but goes back in on its own?","Grade 2",["Grade 1","Grade 3","Grade 4"],"Grade 1 is asymptomatic or has some bleeding. Grade 4 cannot be pushed back.",HRL+", slide 9");
T("Hemorrhoids: grades",3,"Which procedure fits grade 1 or 2 internal hemorrhoids (maybe 3)?","Rubber band ligation",["Hemorrhoidectomy","Sitz bath alone","Oral diosmin"],"Hemorrhoidectomy is for grade 3 or 4.",HRL+", slide 12");
T("Hemorrhoids: exclusions",1,"Which patient should be referred instead of self-treated?","A patient with black tarry stools",["A patient with mild itching after bowel movements for 2 days","A patient with mild burning that improves after a sitz bath","A 30-year-old with a minor anal irritation and no bleeding"],"Exclusions include bleeding, seepage, thrombosis, prolapse (especially grade III or IV), acute onset of pain, black tarry stools and moderate to severe itching, burning, inflammation or swelling.",HRL+", slide 10");
T("Hemorrhoids: exclusions",1,"How long can minor hemorrhoid symptoms be self-treated before referral?","7 days",["1 day","3 days","30 days"],"Symptoms that do not respond to 7 days of self-treatment need a medical referral.",HRL+", slide 10");
T("Hemorrhoids: exclusions",1,"Below what age should anorectal symptoms be referred?","12 years",["2 years","5 years","18 years"],"Children under 12 are excluded from self-treatment.",HRL+", slide 10");
T("Hemorrhoids: exclusions",2,"Which history is an exclusion for self-treating anorectal symptoms?","Crohn disease or ulcerative colitis that can cause bleeding",["Mild seasonal allergies","A past sprained ankle","Use of a daily multivitamin"],"Other exclusions are a family history of colon cancer and a previously diagnosed anorectal problem such as abscess, fistula or fissure.",HRL+", slide 10");
T("Hemorrhoids: non-drug care",1,"What daily fiber and fluid target helps prevent straining?","25 to 40 g of fiber and 6 to 8 glasses of water",["5 g of fiber and 2 glasses of water","100 g of fiber and 1 glass of water","10 g of fiber and 12 glasses of water"],"Reducing constipation reduces pressure on the veins.",HRL+", slide 11");
T("Hemorrhoids: non-drug care",1,"How long should a patient sit on the toilet?","Less than 2 to 5 minutes",["10 to 15 minutes","20 to 30 minutes","As long as needed"],"Prolonged sitting on hard surfaces raises pressure and blood pooling.",HRL+", slide 11");
T("Hemorrhoids: non-drug care",2,"What is the best way to clean the area?","Soap and water with blotting rather than wiping",["Dry toilet paper with firm wiping","Alcohol-based wipes","Scrubbing with a washcloth"],"Soaking in warm water at 120 F or less for 10 to 20 minutes, 2 to 4 times a day, also reduces irritation.",HRL+", slide 11");
T("Hemorrhoids: non-drug care",2,"Which medicines treat the constipation that contributes to hemorrhoids?","Docusate and polyethylene glycol",["Loperamide","Phenylephrine","Hydrocortisone"],"Reducing constipation lowers straining. The other options treat diarrhea or hemorrhoid symptoms.",HRL+", slide 13");
T("Hemorrhoids: OTC agents",2,"Which class shrinks hemorrhoidal tissue?","Vasoconstrictors such as phenylephrine",["Local anesthetics","Protectants","Astringents"],"Vasoconstrictors restrict blood flow to the veins. They can be absorbed systemically.",HRL+", slide 14");
T("Hemorrhoids: OTC agents",2,"Which class blocks sodium channels to reduce pain, itching and burning?","Local anesthetics such as pramoxine or dibucaine",["Protectants","Corticosteroids","Vasoconstrictors"],"Local anesthetics are for external use. Prolonged use can cause contact dermatitis.",HRL+", slide 14");
T("Hemorrhoids: OTC agents",2,"Why is glycerin only for external use?","It stimulates bowel movements",["It is a vasoconstrictor","It is absorbed through the skin","It causes tissue atrophy"],"Protectants such as cocoa butter, petrolatum and zinc oxide are fine for both. Glycerin is external only.",HRL+", slide 14");
T("Hemorrhoids: OTC agents",2,"Which class helps with inflammation?","Corticosteroids such as hydrocortisone",["Protectants","Astringents","Vasoconstrictors"],"Hydrocortisone helps itching, swelling, burning, inflammation and irritation, with a slower onset of about 12 hours. Chronic use can cause tissue atrophy.",HRL+", slides 14, 15");
T("Hemorrhoids: OTC agents",2,"Which ingredient class helps swelling but NOT itching, burning or irritation?","Vasoconstrictors",["Protectants","Local anesthetics","Astringents"],"Phenylephrine only reduces swelling. Hydrocortisone covers all five symptoms.",HRL+", slide 15");
T("Hemorrhoids: OTC agents",1,"Which hydrocortisone form is prescription only?","Internal products such as the suppository",["External hydrocortisone 1% ointment","Hydrocortisone 1% cream","Hydrocortisone wipes"],"Anusol-HC 25 mg suppositories are Rx only. Hydrocortisone is OTC for external use.",HRL+", slides 14, 19");
T("Hemorrhoids: OTC agents",2,"What does witch hazel do?","Acts as an astringent to dry tissue and relieve itching and burning",["Shrinks hemorrhoids by vasoconstriction","Blocks sodium channels","Stimulates bowel movements"],"Witch hazel is external only. Zinc oxide and calamine are astringents too.",HRL+", slide 14");
T("Hemorrhoids: OTC agents",2,"What are the ingredients in Preparation H suppositories?","Cocoa butter (protectant) and phenylephrine (vasoconstrictor)",["Hydrocortisone and zinc oxide","Witch hazel and glycerin","Dibucaine and petrolatum"],"They are for rectal use only. Calmol 4 uses cocoa butter and zinc oxide instead.",HRL+", slide 17");
T("Hemorrhoids: OTC agents",2,"Which ingredient is in Preparation H wipes?","Witch hazel 50%",["Phenylephrine","Hydrocortisone","Cocoa butter"],"Witch hazel is an astringent and the wipes are for external use only.",HRL+", slide 20");
T("Hemorrhoids: special situations",2,"Which hemorrhoid products are appropriate for a pregnant patient?","External products as self-care, and internal products only with a prescriber, using protectants only",["Any product including phenylephrine","Internal hydrocortisone as self-care","Glycerin suppositories"],"Internal products have more systemic absorption that can pose a risk to the fetus. If an internal product is preferred, use protectants except glycerin.",HRL+", slides 16, 23");
T("Hemorrhoids: special situations",3,"Which patient should avoid a phenylephrine hemorrhoid product?","A patient with hypertension",["A patient with mild constipation","A patient on a statin","A patient with seasonal allergies"],"Alpha-1 agonism can worsen hypertension or an enlarged prostate. Heart disease, diabetes, thyroid disease and antidepressant use also need a prescriber check.",HRL+", slides 16, 23");
T("Hemorrhoids: special situations",3,"Why do MAOIs and tricyclic antidepressants matter with phenylephrine?","They raise phenylephrine levels",["They block its absorption","They turn it into a steroid","They make it work faster in the gut"],"Patients on antidepressants should get a hemorrhoid product without a vasoconstrictor.",HRL+", slides 16, 23");
T("Hemorrhoids: special situations",3,"A patient with heart disease and mild itching and burning needs an OTC product. Which is best?","A product without a vasoconstrictor",["A phenylephrine suppository","A product containing ephedrine","Any combination product"],"The algorithm says to use hemorrhoidal agents except vasoconstrictors for cardiovascular disease, hypertension, thyroid disease, diabetes, enlarged prostate or antidepressant use.",HRL+", slide 23");
T("Hemorrhoids: counseling",1,"How should a patient lie to insert a suppository?","On their side",["Standing up","Sitting upright","On their stomach"],"Insert about 1 inch into the anal canal, then lie still for at least 5 minutes, ideally 15 to 20.",HRL+", slide 26");
T("Hemorrhoids: counseling",2,"How many times per day can most hemorrhoid products be used?","Up to 6 times, or 4 times for vasoconstrictors and hydrocortisone",["Once a day","Up to 10 times","Only at bedtime"],"Improvement should occur in a few days. Refer if there is no improvement in 7 days.",HRL+", slide 26");
T("Hemorrhoids: counseling",2,"Which product claim is supported for combination hemorrhoid products?","They are reasonable to try for several symptoms but are no more effective than single agents",["They work twice as fast","They are safer than single agents","They can replace diet changes"],"Choose by location, patient factors and what form the patient will use.",HRL+", slide 25");
T("Hemorrhoids: complementary",3,"What is the evidence for diosmin plus hesperidin in hemorrhoids?","It reduced itching, bleeding and leakage but did not decrease pain",["It reduced pain best","It heals grade 4 hemorrhoids","It is Rx only"],"The usual course is 2 weeks at 1200/300 mg BID. Most studies were manufacturer funded.",HRL+", slide 24");
